const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get orders
let orders = db.prepare(\"SELECT * FROM orders WHERE customer_id = 'cust_001'\").all();
console.log('Orders:', JSON.stringify(orders, null, 2));

// Get payment methods
let pm = db.prepare(\"SELECT * FROM rt_payment_methods WHERE user_id = 'cust_001'\").all();
