// Get order items for those orders
if (orders.length > 0) {
  const orderIds = orders.map(o => o.order_id);
  for (const oid of orderIds) {
    let items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(oid);
    console.log('Items for ' + oid + ':', JSON.stringify(items, null, 2));
  }
}
"

